{"command": "cd /workspace/vllm-project/vllm && cat > /tmp/extract.py << 'EOF'
import sys

def extract_body(filename):
    with open(filename, 'r') as f:
        lines = f.readlines()
    start = 0
    for i, line in enumerate(lines):
        if line.strip().startswith('@'):
            start = i
            break
    # include from start to end
    body_lines = lines[start:]
    # remove trailing empty lines
    while body_lines and body_lines[-1].strip() == '':
        body_lines.pop()
    return ''.join(body_lines)

if __name__ == '__main__':
    import json
    expand_kernel = extract_body('/tmp/expand_kernel_fixed.py')
    expand_wrapper = extract_body('/tmp/expand_wrapper.py')
    shrink_kernel = extract_body('/tmp/shrink_kernel_fixed.py')
    shrink_wrapper = extract_body('/tmp/shrink_wrapper.py')
    result = {
        "vllm/lora/ops/triton_ops/v1/v1_expand.py": {
            "_v1_expand_kernel": expand_kernel,
            "_v1_expand": expand_wrapper,
        },
        "vllm/lora/ops/triton_ops/v1/v1_shrink.py": {
            "_v1_shrink_kernel": shrink_kernel,
            "_v1_shrink": shrink_wrapper,
        }
    }
    with open('/prediction.json', 'w') as f:
        json.dump(result, f, indent=2)
EOF"}

